import{_ as t,o as e,c as o,a5 as n}from"./chunks/framework.CsGesDJn.js";const k=JSON.parse('{"title":"UC — Kanban Board Task View","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-7-kanban-board-task-view/spec.md","filePath":"feature/content-task-workflow/3-6-7-kanban-board-task-view/spec.md"}'),i={name:"feature/content-task-workflow/3-6-7-kanban-board-task-view/spec.md"};function r(c,a,h,s,d,l){return e(),o("div",null,[...a[0]||(a[0]=[n(`<h1 id="uc-—-kanban-board-task-view" tabindex="-1">UC — Kanban Board Task View <a class="header-anchor" href="#uc-—-kanban-board-task-view" aria-label="Permalink to &quot;UC — Kanban Board Task View&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.6.7</td></tr><tr><td>Feature</td><td>Kanban Board Task View</td></tr><tr><td>Domain</td><td>Content &amp; Workflow (FR 3.6)</td></tr><tr><td>Role</td><td>CREATOR, CLIENT, MANAGER</td></tr><tr><td>Version</td><td>2.0 (V2 — nghiệp vụ mới, 2026-09-14)</td></tr><tr><td>Trạng thái tài liệu</td><td>Draft — BA confirmed, chưa code</td></tr></tbody></table><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Board kéo thả trạng thái công việc kiểu Jira — làm thêm 3 kiểu board khác nhau theo yêu cầu CSV.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>Là một Creator, Client, hoặc Manager, tôi muốn xem Task theo dạng Kanban board, để kéo thả đổi trạng thái công việc trực quan.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ul><li>Board mặc định: cột theo trạng thái Approval Sequence (Backlog / Assigned / In Progress / Review / Completed).</li><li><strong>Làm thêm 3 kiểu board khác</strong> (theo CSV, chưa chỉ rõ tiêu chí — đề xuất 3 kiểu: theo Assignee, theo Loại Task (Post/Livestream/Survey), theo Campaign) — cần xác nhận tiêu chí cụ thể với Trung khi thiết kế UI.</li><li>Kéo Task sang cột khác → tương đương thao tác approve/reject tùy vị trí cột (map với Approval Sequence, FR 3.6.9) — chỉ Manager/Creator kéo được, Client chỉ xem hoặc kéo trong phạm vi quyền approve của họ.</li></ul><h2 id="_4-ui-ux" tabindex="-1">4. UI / UX <a class="header-anchor" href="#_4-ui-ux" aria-label="Permalink to &quot;4. UI / UX&quot;">​</a></h2><ul><li>Trang <code>/workspaces/:id/tasks?view=kanban&amp;groupBy=status|assignee|type|campaign</code>.</li></ul><h2 id="_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" tabindex="-1">5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật) <a class="header-anchor" href="#_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" aria-label="Permalink to &quot;5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/workspaces/{id}/tasks?view=kanban&amp;groupBy=status</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: { &quot;columns&quot;: [{ &quot;key&quot;, &quot;label&quot;, &quot;tasks&quot;: [...] }] } }</span></span></code></pre></div><h2 id="_6-error-handling" tabindex="-1">6. Error Handling <a class="header-anchor" href="#_6-error-handling" aria-label="Permalink to &quot;6. Error Handling&quot;">​</a></h2><ul><li>Kéo Task vào cột không hợp lệ theo Approval Sequence hiện tại (ví dụ kéo thẳng từ Assigned sang Completed, bỏ qua Review) → 409 <code>INVALID_STATUS_TRANSITION</code>.</li></ul><h2 id="_7-edge-cases" tabindex="-1">7. Edge Cases <a class="header-anchor" href="#_7-edge-cases" aria-label="Permalink to &quot;7. Edge Cases&quot;">​</a></h2><ul><li>Client kéo Task sang cột &#39;Reject&#39; → phải map đúng vào action reject của Approval Sequence, quay Task về <code>ASSIGNED</code> (theo state machine đã xác nhận).</li></ul><h2 id="_8-definition-of-done" tabindex="-1">8. Definition of Done <a class="header-anchor" href="#_8-definition-of-done" aria-label="Permalink to &quot;8. Definition of Done&quot;">​</a></h2><ul><li>4 kiểu board hoạt động, kéo thả map đúng vào state machine Approval Sequence.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Không có.</li></ul><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../../BA/05-content-task-workflow.html">05-content-task-workflow.md</a>, <a href="./../../../BA/12-state-machines.html">12-state-machines.md</a></p>`,22)])])}const p=t(i,[["render",r]]);export{k as __pageData,p as default};
